/**
 * One delivered close selected for the current binding, named by its existing event position.
 */
export type ApprovedClose = { tab: TabId, seq: number, };

/**
 * The tab of the run's own page, once the call that needed it opened it. Plain ids rather
 * than the page brand, so the page prelude can give the script's existing `page` its tab
 * instead of reviving a second object for it.
 */
export type DefaultPage = { tab: number, };

/**
 * Whether an operation's side effect happened, as far as Neo can know. It serializes as its
 * stored name, `as_str`.
 */
export type Delivery = "not_sent" | "done" | "unknown";

/**
 * The JS wire form of an `OpReply`: `{"ok": value, "pages": […]}` or `{"err": {…}, "pages":
 * […]}`, plus `defaultPage` once the call opened the run's own page, `pickedPage` once a task
 * pick bound it, and `pumped` once an op ordered its answer after event-pump replies. Protocol translation only: the door decided
 * every value in it. Every field after `ok`/`err` is the same in both shapes.
 */
export type Envelope = { 
/**
 * Its result, typed per op by the prelude's generated `OpOutputs`.
 */
ok: unknown, 
/**
 * The pages the op touched, its target first.
 */
pages: Array<PageFact>, 
/**
 * The host observation that read `pages`, absent when the op completed none.
 */
observed?: Observation, 
/**
 * The run's own page, on the reply of the call that opened it.
 */
defaultPage?: DefaultPage, 
/**
 * The tab a task pick bound the run's own page to (`OpReply::picked_page`): the
 * prelude's `page` takes it unless the script already holds another Page for it.
 */
pickedPage?: DefaultPage, 
/**
 * `OpReply::pumped`: the prelude dispatches that many event-pump replies before it
 * hands the script this one. Absent for none.
 */
pumped?: number, 
/**
 * The navigation publications whose producers have answered (`page.goto` and the
 * history ops' `publication.id`). Absent for none.
 */
completedNavigations?: Array<number>, 
/**
 * The browser's frame-change head (`Observer::frames_head`): it moves whenever any
 * tab's frames change. The prelude reads again the trees of the pages the script uses
 * once it passes the head their tree was read at, so a tab this op did not touch, whose
 * facts the reply does not carry, is caught too. Absent before any change.
 */
framesHead?: number, } | { 
/**
 * The failure as the door decided it.
 */
err: ErrBody, 
/**
 * As for `Ok`.
 */
pages: Array<PageFact>, 
/**
 * As for `Ok`.
 */
observed?: Observation, 
/**
 * As for `Ok`.
 */
defaultPage?: DefaultPage, 
/**
 * As for `Ok`.
 */
pickedPage?: DefaultPage, 
/**
 * As for `Ok`.
 */
pumped?: number, 
/**
 * As for `Ok`.
 */
completedNavigations?: Array<number>, 
/**
 * As for `Ok`.
 */
framesHead?: number, };

/**
 * The fields of the script's `NeoError`, named as the trace names them. errors.ts copies all
 * but `message` and `matcher` onto the error the script catches.
 */
export type ErrBody = { 
/**
 * The stable code (`wait_timeout`, `invalid_input`, …).
 */
code: string, 
/**
 * Who must change to fix it.
 */
owner: ErrorOwner, 
/**
 * Whether the op's side effect happened.
 */
delivery: Delivery, 
/**
 * Whether repeating the op is safe.
 */
retryable: boolean, 
/**
 * The op that failed.
 */
operationId: OperationId, 
/**
 * Makes the bootstrap throw a `TimeoutError`.
 */
timeout: boolean, 
/**
 * The human message, which already starts with the method the script called.
 */
message: string, 
/**
 * A failed `expect` matcher's facts, which the bootstrap puts on the error as
 * `matcherResult` for the expect prelude to complete.
 */
matcher?: unknown, };

/**
 * Whose behavior must change to fix a failure.
 */
export type ErrorOwner = "neo" | "script" | "website" | "host";

/**
 * Freshness of a batch of page facts. Neither counter is a page identity.
 */
export type Observation = { 
/**
 * The host's read serial: a later batch of facts replaces an earlier one, never the reverse.
 */
seq: number, 
/**
 * The page-event log's head before this read.
 */
events: number, 
/**
 * Whether the operation's payload describes the binding read by this observation.
 */
payloadCurrent?: boolean, 
/**
 * Close records applied by this observation, consumed in event order by the prelude.
 * Absent when there are none.
 */
closes?: Array<ApprovedClose>, };

/**
 * One SDK operation: the run it belongs to and its admission order within that run. On the wire
 * it is the string `{run}.{seq}`.
 */
export type OperationId = string;

/**
 * One page as a reply reports it. Deliberately not a page brand (no `$neo`), so the
 * bootstrap never revives a fact into a `Page` object. Its viewport configuration initializes
 * synchronous accessors in each new agent realm, independently of the owner's temporary fit.
 */
export type PageFact = { 
/**
 * The browser's tab id.
 */
tab: TabId, 
/**
 * The owning task now; task-less tabs serialize as null.
 */
taskId: string | null, 
/**
 * `None` (null) once closed.
 */
url: string | null, 
/**
 * `None` (null) once closed.
 */
title: string | null, 
/**
 * Whether the tab is gone.
 */
closed: boolean, 
/**
 * Script configuration, carried to each fresh realm; owner fits never replace it.
 */
viewportSize?: Size, 
/**
 * Captured under the same observation serial as the page cache read.
 */
workers?: Array<WorkerInfo>, 
/**
 * The tab's frame-tree version: it moves when the tab's frames change (a child frame
 * attaches, leaves or navigates, an out-of-process frame's session comes or goes, the main
 * frame commits), never on a read of the tree. A run that holds the tab's tree reads it
 * again before the script's operation resolves once this passes the version it read at.
 * Absent before the tab's frames first changed while Neo followed it.
 */
framesChanged?: number, };

/**
 * A live browser tab resolved by the dispatcher before policies run. This is the only page
 * identity on the wire, where it is the page brand `{"$neo": "page", "tab": …}`; core's private
 * cache id is held separately for one operation.
 */
export type PageRef = { $neo: 'page', tab: TabId, };

/**
 * The run's init: the bootstrap's `__neo.run` hands it to each parameter's build
 * (`__neo.provide`), which the prelude's bridge.ts `provide` reads. `run_script` and the hosted
 * run send the same text.
 */
export type RunInit = { 
/**
 * The task's tab when the run service knows one; null opens one on the first op that
 * names the page.
 */
page: PageRef | null, 
/**
 * Every tab open when the run started, as reply facts describe them, in
 * `context.pages()`'s order; empty when the run service could not list them.
 */
pages: Array<PageFact>, 
/**
 * The host observation that read `pages`, which later replies' observations follow.
 */
observed: Observation | null, };

/**
 * A width and height, as a page's viewport size is reported. neo-server's run envelope carries
 * it, and prints it as TypeScript under the `ts-rs` feature.
 */
export type Size = { width: number, height: number, };

export type TabId = number;

/**
 * A worker identity in the host protocol, independent of the browser adapter. The prelude's
 * `Worker` objects are keyed by `id`.
 */
export type WorkerInfo = { id: string, url: string, };
